    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TargetType {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .post(postId: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .comment(commentId: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
